1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Derives an owner's {@code customerCode} — the owner's region-and-hash identity,
8	 * formatted {@code <REGION>-<HASH8>}:
9	 *
10	 * <ul>
11	 * <li>{@code REGION} is the region code derived from the postcode: look the postcode up
12	 * against the inclusive region ranges (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) and,
13	 * only when the postcode is absent or in no known range, fall back to the fixed
14	 * city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD), else
15	 * {@code UNKNOWN}.</li>
16	 * <li>{@code HASH8} is the first 8 upper-case hex characters of SHA-256 over
17	 * {@code normalizedTelephone + lastName}, where the telephone is normalized to E.164 form
18	 * (an absent or unparseable telephone contributes an empty string).</li>
19	 * </ul>
20	 *
21	 * <p>The whole owner identity — the {@code customerCode} itself, the values built from it
22	 * (membership number and its Luhn check digit), the create audit record and the derived
23	 * locality — flows from this single value. There is no sequence number.
24	 *
25	 * <p>Composition and decomposition of the code format live together here: {@link #of} builds
26	 * a code, {@link #regionOf} reads the region back out of one, and {@link #luhn} is the check
27	 * over its digits. Callers (the owner mapper's {@code locality} and {@code checkDigit}) delegate
28	 * rather than re-deriving the format, so it is described in one place.
29	 *
30	 * <p>A plain utility (not an OfficeFloor function), so it may expose helpers without
31	 * tripping the one-public-method-per-function rule.
32	 */
33	public final class OwnerCustomerCode {
34	
35	    /** City -> canonical region, matching the fixed table used to validate postcodes. */
36	    private static final Map<String, String> CITY_REGION = Map.of(
37	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
38	
39	    /** Region -> inclusive 4-digit postcode range {low, high}. */
40	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
41	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
42	
43	    private OwnerCustomerCode() {
44	    }
45	
46	    /** The full {@code <REGION>-<HASH8>} customer code for the given owner fields. */
47	    public static String of(String postcode, String city, String telephone, String lastName) {
48	        return region(postcode, city) + "-" + hash8(telephone, lastName);
49	    }
50	
51	    /**
52	     * The REGION segment encoded in an existing customer code, i.e. the part preceding the
53	     * {@code -<HASH8>} suffix (see {@link #of}). Returns {@code null} when {@code code} is absent
54	     * or carries no region segment. The inverse of {@link #of}: callers read the region back out
55	     * of the code here instead of re-parsing the format themselves.
56	     */
57	    public static String regionOf(String code) {
58	        if (code == null) {
59	            return null;
60	        }
61	        int dash = code.indexOf('-');
62	        return dash > 0 ? code.substring(0, dash) : null;
63	    }
64	
65	    /**
66	     * The Luhn check digit (0-9) computed over the decimal digits contained in {@code s}
67	     * (non-digit characters are ignored). Kept beside the code it checks so the code format and
68	     * the values derived from it share one home.
69	     */
70	    public static int luhn(String s) {
71	        int sum = 0;
72	        boolean dbl = true;
73	        for (int i = s.length() - 1; i >= 0; i--) {
74	            char c = s.charAt(i);
75	            if (c < '0' || c > '9') {
76	                continue;
77	            }
78	            int d = c - '0';
79	            if (dbl) {
80	                d *= 2;
81	                if (d > 9) {
82	                    d -= 9;
83	                }
84	            }
85	            sum += d;
86	            dbl = !dbl;
87	        }
88	        return (10 - (sum % 10)) % 10;
89	    }
90	
91	    /**
92	     * The region code derived from the postcode (range lookup), falling back to the fixed
93	     * city-to-region table when the postcode is absent or in no known range, else
94	     * {@code UNKNOWN}.
95	     */
96	    public static String region(String postcode, String city) {
97	        if (postcode != null) {
98	            try {
99	                int value = Integer.parseInt(postcode.trim());
100	                for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
101	                    int[] range = entry.getValue();
102	                    if (value >= range[0] && value <= range[1]) {
103	                        return entry.getKey();
104	                    }
105	                }
106	            }
107	            catch (NumberFormatException ex) {
108	                // not a numeric postcode; fall back to the city table
109	            }
110	        }
111	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
112	    }
113	
114	    /**
115	     * The region for a city by the fixed city-to-region table
116	     * ({@code Sydney->NSW, Melbourne->VIC, Brisbane->QLD}), or {@code null} when the city has
117	     * no known region. Unlike {@link #region}, this does not fall back to {@code UNKNOWN}; it
118	     * exposes the raw city table so callers such as {@code ValidatePostcode} share this one
119	     * source of the region reference data.
120	     */
121	    public static String regionForCity(String city) {
122	        return CITY_REGION.get(city);
123	    }
124	
125	    /**
126	     * The inclusive 4-digit postcode range {@code {low, high}} pinned for a region (NSW
127	     * 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code null} when the region has no pinned
128	     * range. The returned array is a copy, so callers cannot mutate the shared table.
129	     */
130	    public static int[] postcodeRange(String region) {
131	        int[] range = REGION_POSTCODES.get(region);
132	        return range == null ? null : range.clone();
133	    }
134	
135	    /**
136	     * The first 8 upper-case hex characters of SHA-256 over {@code normalizedTelephone +
137	     * lastName}, where the telephone is normalized to E.164 (an absent or unparseable
138	     * telephone, or an absent last name, contributes an empty string).
139	     */
140	    public static String hash8(String telephone, String lastName) {
141	        String tel = E164Telephone.normalizeOrNull(telephone);
142	        String normalizedTelephone = tel == null ? "" : tel;
143	        String last = lastName == null ? "" : lastName;
144	        return Sha256.hex(normalizedTelephone + last).substring(0, 8).toUpperCase(Locale.ROOT);
145	    }
146	}
