1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	/**
6	 * Fiscal-year arithmetic. The fiscal year starts on 1 July and is identified by the
7	 * calendar year in which it ends: a date in July-December belongs to the fiscal year ending
8	 * the following June ({@code year + 1}); a date in January-June belongs to the fiscal year
9	 * ending that same June ({@code year}).
10	 *
11	 * <p>Used for the date-derived owner values (the membership number's year segment, the
12	 * {@code fiscalYear} field, and tenure), all taken from the business-day-adjusted
13	 * {@code registrationDate}.
14	 *
15	 * <p>A plain utility (not an OfficeFloor function).
16	 */
17	public final class FiscalYear {
18	
19	    private FiscalYear() {
20	    }
21	
22	    /** The fiscal year (as a full calendar year, e.g. 2026) that {@code date} falls in. */
23	    public static int of(LocalDate date) {
24	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
25	    }
26	
27	    /** The fiscal year formatted {@code FY<YY>} (the last two digits), e.g. {@code FY26}. */
28	    public static String label(LocalDate date) {
29	        return String.format("FY%02d", of(date) % 100);
30	    }
31	
32	    /** Whole fiscal years elapsed from {@code from} to {@code to} (0 within the same fiscal year). */
33	    public static int elapsed(LocalDate from, LocalDate to) {
34	        return of(to) - of(from);
35	    }
36	}
