1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	import java.util.concurrent.atomic.AtomicLong;
6	
7	import org.slf4j.Logger;
8	import org.slf4j.LoggerFactory;
9	
10	import net.officefloor.plugin.variable.Val;
11	import tools.jackson.databind.ObjectMapper;
12	import org.springframework.samples.petclinic.mapper.OwnerMapper;
13	import org.springframework.samples.petclinic.model.Owner;
14	
15	/**
16	 * Emits audit output on successful owner creation via the dedicated {@code AUDIT}
17	 * logger.
18	 *
19	 * <p>Two things are emitted per create:
20	 * <ol>
21	 * <li>a human-readable audit line carrying the owner id, the {@code customerCode},
22	 * the {@code registrationDate}, the {@code membershipLevel} and the
23	 * {@code membershipNumber}; and
24	 * <li>an immutable structured event, a JSON object
25	 * {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}},
26	 * where {@code seq} is a monotonically increasing integer across all creates.
27	 * </ol>
28	 *
29	 * <p>The event carries the owner's <em>current primary identifier</em>. Today that
30	 * identifier is the {@code customerCode}; when it is later unified into the
31	 * {@code memberId}, only {@link #primaryIdentifier(Owner)} changes and the event
32	 * follows without touching the emission below.
33	 *
34	 * <p>Runs after {@code SaveOwner} so the owner id has been assigned.
35	 */
36	public class AuditOwnerCreated {
37	
38	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
39	
40	    /** Monotonically increasing sequence shared across every owner-create event. */
41	    private static final AtomicLong SEQUENCE = new AtomicLong();
42	
43	    private static final ObjectMapper JSON = new ObjectMapper();
44	
45	    public void service(@Val Owner owner, OwnerMapper ownerMapper) {
46	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
47	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
48	                ownerMapper.toMembershipLevel(owner), ownerMapper.toMembershipNumber(owner));
49	
50	        Map<String, Object> event = new LinkedHashMap<>();
51	        event.put("seq", SEQUENCE.incrementAndGet());
52	        event.put("ownerId", owner.getId());
53	        event.put("customerCode", primaryIdentifier(owner));
54	        event.put("membershipLevel", ownerMapper.toMembershipLevel(owner));
55	        event.put("event", "OWNER_CREATED");
56	        AUDIT.info(JSON.writeValueAsString(event));
57	    }
58	
59	    /**
60	     * The owner's current primary identifier. Today this is the {@code customerCode};
61	     * change this single method when the identifier is unified into the {@code memberId}.
62	     */
63	    private static String primaryIdentifier(Owner owner) {
64	        return owner.getCustomerCode();
65	    }
66	}
