1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "selfLink", expression = "java(toSelfLink(owner))")
22	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "salutation", expression = "java(toSalutation(owner))")
24	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
25	    @Mapping(target = "membershipNumber", expression = "java(toMembershipNumber(owner))")
26	    @Mapping(target = "checkDigit", expression = "java(toCheckDigit(owner))")
27	    @Mapping(target = "membershipPoints", expression = "java(toMembershipPoints(owner))")
28	    @Mapping(target = "membershipLevel", expression = "java(toMembershipLevel(owner))")
29	    @Mapping(target = "locality", expression = "java(toLocality(owner))")
30	    @Mapping(target = "timezone", expression = "java(toTimezone(owner))")
31	    @Mapping(target = "ownerSegment", expression = "java(toOwnerSegment(owner))")
32	    @Mapping(target = "contactPreference", expression = "java(toContactPreference(owner))")
33	    @Mapping(target = "identityKey", expression = "java(toIdentityKey(owner))")
34	    @Mapping(target = "ageBand", expression = "java(toAgeBand(owner))")
35	    @Mapping(target = "telephoneDisplay", expression = "java(toTelephoneDisplay(owner))")
36	    @Mapping(target = "fiscalYear", expression = "java(toFiscalYear(owner))")
37	    OwnerDto toOwnerDto(Owner owner);
38	
39	    /**
40	     * Derives the owner's {@code selfLink}: the canonical API path {@code /api/owners/} followed by
41	     * the owner's id. Returns null when the owner has no id (e.g. before it has been persisted).
42	     */
43	    default String toSelfLink(Owner owner) {
44	        if (owner.getId() == null) {
45	            return null;
46	        }
47	        return "/api/owners/" + owner.getId();
48	    }
49	
50	    /**
51	     * Derives the owner's {@code fiscalYear}: the fiscal year of the business-day-adjusted
52	     * {@code registrationDate}, formatted {@code FY<YY>} (see
53	     * {@link org.springframework.samples.petclinic.rest.function.owner.FiscalYear}). Returns null
54	     * when no registration date is present (e.g. unmigrated seed data).
55	     */
56	    default String toFiscalYear(Owner owner) {
57	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
58	        if (registrationDate == null) {
59	            return null;
60	        }
61	        return org.springframework.samples.petclinic.rest.function.owner.FiscalYear.label(registrationDate);
62	    }
63	
64	    /**
65	     * Derives the owner's {@code salutation}: the {@code title} followed by a single space and the
66	     * {@code lastName} when a title is present, or just the {@code lastName} when no title was
67	     * supplied.
68	     */
69	    default String toSalutation(Owner owner) {
70	        String title = owner.getTitle();
71	        if (title == null || title.isBlank()) {
72	            return owner.getLastName();
73	        }
74	        return title + " " + owner.getLastName();
75	    }
76	
77	    /**
78	     * Derives the owner's {@code telephoneDisplay}: the stored E.164 {@code telephone} formatted
79	     * for humans (see {@link org.springframework.samples.petclinic.rest.function.owner.E164Telephone#display}).
80	     * The raw {@code telephone} is left in E.164 form.
81	     */
82	    default String toTelephoneDisplay(Owner owner) {
83	        return org.springframework.samples.petclinic.rest.function.owner.E164Telephone
84	                .display(owner.getTelephone());
85	    }
86	
87	    /**
88	     * Derives the owner's {@code ageBand} from its {@code birthDate} measured against its
89	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64,
90	     * {@code SENIOR} at 65 or older. Returns null when either date is absent (so no band is
91	     * reported for owners with no supplied birth date).
92	     */
93	    default org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
94	        java.time.LocalDate birthDate = owner.getBirthDate();
95	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
96	        if (birthDate == null || registrationDate == null) {
97	            return null;
98	        }
99	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
100	        if (age < 18) {
101	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.MINOR;
102	        }
103	        if (age < 65) {
104	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.ADULT;
105	        }
106	        return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.SENIOR;
107	    }
108	
109	    /**
110	     * Derives the owner's {@code identityKey}: the single value that consolidates all
111	     * duplicate detection, the SHA-256 hex digest of {@code normalizedTelephone + '|' +
112	     * (email or empty) + '|' + soundex(lastName)}.
113	     */
114	    default String toIdentityKey(Owner owner) {
115	        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(owner);
116	    }
117	
118	    /**
119	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email is present,
120	     * otherwise {@code PHONE}.
121	     */
122	    default String toContactPreference(Owner owner) {
123	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
124	        return hasEmail ? "EMAIL" : "PHONE";
125	    }
126	
127	    /**
128	     * Derives the owner's locality (region) from its region-and-hash identity: the region encoded
129	     * in the {@code customerCode} (see
130	     * {@link org.springframework.samples.petclinic.rest.function.owner.OwnerCustomerCode#regionOf}).
131	     * Falls back to deriving the region directly from the postcode/city only for unmigrated owners
132	     * that carry no customer code.
133	     */
134	    default String toLocality(Owner owner) {
135	        String region = org.springframework.samples.petclinic.rest.function.owner.OwnerCustomerCode
136	                .regionOf(owner.getCustomerCode());
137	        if (region != null) {
138	            return region;
139	        }
140	        return org.springframework.samples.petclinic.rest.function.owner.OwnerCustomerCode
141	                .region(owner.getPostcode(), owner.getCity());
142	    }
143	
144	    /** Region -> IANA timezone, the pinned region-to-timezone table. */
145	    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
146	            "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
147	
148	    /**
149	     * Derives the owner's {@code timezone}: the IANA name for the owner's locality/region via
150	     * the fixed region-to-timezone table (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
151	     * QLD-&gt;Australia/Brisbane). Returns null when the region yields no known timezone (e.g.
152	     * an {@code UNKNOWN} locality).
153	     */
154	    default String toTimezone(Owner owner) {
155	        return REGION_TIMEZONE.get(toLocality(owner));
156	    }
157	
158	    /** The known regions used to distinguish a METRO area from a REGIONAL one. */
159	    java.util.Set<String> KNOWN_REGIONS = java.util.Set.of("NSW", "VIC", "QLD");
160	
161	    /**
162	     * Derives the owner's {@code ownerSegment}, formatted {@code <TIER>_<AREA>}: TIER is
163	     * {@code PREMIUM} when the {@code membershipLevel} is 3 or more, otherwise {@code STANDARD};
164	     * AREA is {@code METRO} when the {@code locality} is a known region (NSW, VIC or QLD),
165	     * otherwise {@code REGIONAL}. One of {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL},
166	     * {@code STANDARD_METRO} or {@code STANDARD_REGIONAL}.
167	     */
168	    default String toOwnerSegment(Owner owner) {
169	        Integer membershipLevel = toMembershipLevel(owner);
170	        String tier = membershipLevel != null && membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
171	        String area = KNOWN_REGIONS.contains(toLocality(owner)) ? "METRO" : "REGIONAL";
172	        return tier + "_" + area;
173	    }
174	
175	    /**
176	     * Derives the owner's membership points: start at 0; add 2 when an email is present; add 1
177	     * when the owner has no namesakes ({@code namesakeCount} is 0); add 2 for a household of 3 or
178	     * more ({@code householdSize} at least 3); add 3 for tenure of at least one elapsed fiscal
179	     * year (the {@code registrationDate}'s fiscal year is earlier than the current fiscal year,
180	     * fiscal years starting 1 July). A newly created owner has zero tenure.
181	     */
182	    default Integer toMembershipPoints(Owner owner) {
183	        int points = 0;
184	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
185	        if (hasEmail) {
186	            points += 2;
187	        }
188	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
189	        if (unique) {
190	            points += 1;
191	        }
192	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
193	            points += 2;
194	        }
195	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
196	        if (registrationDate != null && org.springframework.samples.petclinic.rest.function.owner.FiscalYear
197	                .elapsed(registrationDate, java.time.LocalDate.now()) >= 1) {
198	            points += 3;
199	        }
200	        return points;
201	    }
202	
203	    /**
204	     * The owner's numeric membership level (1 to 4). When a level has been stored on the owner
205	     * (the household-capped value assigned at create time, see
206	     * {@link org.springframework.samples.petclinic.rest.function.owner.AssignMembershipLevel}) it
207	     * is returned as-is; otherwise it is derived from {@code membershipPoints} (see
208	     * {@link #deriveMembershipLevel(Owner)}).
209	     */
210	    default Integer toMembershipLevel(Owner owner) {
211	        if (owner.getMembershipLevel() != null) {
212	            return owner.getMembershipLevel();
213	        }
214	        return deriveMembershipLevel(owner);
215	    }
216	
217	    /**
218	     * Derives the owner's numeric membership level (1 to 4) from its {@code membershipPoints},
219	     * before any household cap: level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or more.
220	     */
221	    default Integer deriveMembershipLevel(Owner owner) {
222	        int points = toMembershipPoints(owner);
223	        if (points >= 6) {
224	            return 4;
225	        }
226	        if (points >= 4) {
