package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;

/**
 * Validates an owner's postcode WHEN PRESENT. A postcode is optional: an absent (null)
 * postcode passes untouched, keeping the request contract backward-compatible. When
 * present it must be a 4-digit code and, if the city has a known region, fall within that
 * region's inclusive postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city
 * with no known region accepts any 4-digit postcode. Anything else is rejected 400 via
 * {@link InvalidPostcodeException}.
 */
public class ValidatePostcode {

    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
        String postcode = request.getPostcode();
        if (postcode == null) {
            return; // optional when absent
        }
        if (!postcode.matches("^[0-9]{4}$")) {
            throw new InvalidPostcodeException("Postcode must be a 4-digit code");
        }
        // Region reference data lives once in OwnerCustomerCode; share it rather than copy it.
        String region = OwnerCustomerCode.regionForCity(request.getCity());
        int[] range = region == null ? null : OwnerCustomerCode.postcodeRange(region);
        if (range == null) {
            return; // city with no known region accepts any 4-digit postcode
        }
        int value = Integer.parseInt(postcode);
        if (value < range[0] || value > range[1]) {
            throw new InvalidPostcodeException(
                    "Postcode " + postcode + " is not valid for city " + request.getCity());
        }
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Rejects a create-owner request whose city already contains 50 or more owners. Runs
 * before {@link BuildOwner}, counting existing owners in the requested city (same-city
 * equality as {@link AssignCustomerCode}). At capacity the request is rejected 409 via
 * {@link CityAtCapacityException}.
 */
public class RejectCityAtCapacity {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        long count = CityCapacity.count(request.getCity(), ownerRepository);
        if (count >= CityCapacity.CAPACITY) {
            throw new CityAtCapacityException(
                    "City already contains the maximum number of owners");
        }
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * City capacity rules for owners. A city can hold at most {@link #CAPACITY} owners; a create that
 * would exceed that is rejected (see {@link RejectCityAtCapacity}). A city that already holds
 * between {@link #WARNING_THRESHOLD} and {@code CAPACITY - 1} owners is <em>approaching</em>
 * capacity, surfaced to callers as {@code capacityWarning}.
 *
 * <p>The counted population matches {@link RejectCityAtCapacity}: every owner in the repository
 * whose {@code city} equals the given city (null-safe, same-city equality as
 * {@link AssignCustomerCode}), soft-deleted owners included.
 */
public final class CityCapacity {

    /** Maximum owners a city may hold; a create that would exceed it is rejected. */
    static final int CAPACITY = 50;

    /** A city holding at least this many owners (but below {@link #CAPACITY}) is approaching capacity. */
    private static final int WARNING_THRESHOLD = 40;

    private CityCapacity() {
    }

    /** The number of owners currently in {@code city}. */
    static long count(String city, OwnerRepository ownerRepository) {
        return ownerRepository.findAll().stream()
                .filter(o -> city == null ? o.getCity() == null : city.equals(o.getCity()))
                .count();
    }

    /**
     * Returns true when {@code city} already holds between 40 and 49 owners (approaching the hard
     * capacity limit of 50), otherwise false.
     */
    static boolean warning(String city, OwnerRepository ownerRepository) {
        long count = count(city, ownerRepository);
        return count >= WARNING_THRESHOLD && count < CAPACITY;
    }

    /** Convenience for computing the warning from an owner's city. */
    static boolean warning(Owner owner, OwnerRepository ownerRepository) {
        return warning(owner == null ? null : owner.getCity(), ownerRepository);
    }
}

